export default async function(app){const [buffer,GraphicsLayer,Graphic]=await Promise.all([app.import('esri/geometry/operators/geodesicBufferOperator'),app.import('esri/layers/GraphicsLayer'),app.import('esri/Graphic')]);await buffer.load();const mount=app.getMount('vehicle-follow-controls');mount.replaceChildren();Object.assign(mount.style,{background:'#F8F2E7',color:'#3A3128',padding:'10px',border:'1px solid #E0D2BA',borderRadius:'7px',minWidth:'0',fontSize:'13px'});const el=(tag,text,p)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;p?.append(n);return n;};let ringCount=app.config.ringCount,interval=app.config.intervalMeters,name=null,disposed=false,timer,revision=0,lastPoint=null,lastTime=null,lastResult=null;const distances=()=>Array.from({length:ringCount},(_,i)=>(i+1)*interval);const abort=new AbortController();const status=el('p','Click a vehicle to follow.',mount);status.setAttribute('role','status');status.style.marginTop='0';const form=el('div',undefined,mount);Object.assign(form.style,{display:'grid',gridTemplateColumns:'repeat(2,minmax(0,1fr))',gap:'8px'});function input(label,value,min,max){const box=el('label',label,form);box.style.minWidth='0';const n=el('input',undefined,box);n.type='number';n.min=String(min);n.max=String(max);n.value=String(value);n.setAttribute('aria-label',label);Object.assign(n.style,{display:'block',width:'100%',boxSizing:'border-box',minWidth:'0',marginTop:'4px',padding:'6px 8px',border:'1px solid #E0D2BA',borderRadius:'7px',background:'#F1E7D6',color:'#3A3128',font:'inherit'});return n;}const count=input('Rings',ringCount,1,6);count.step='1';const spacing=input('Ring interval (m)',interval,1,100000);spacing.step='any';const summary=el('p','',mount);Object.assign(summary.style,{fontSize:'11px',color:'#8A7C69',margin:'8px 0'});function sync(){count.value=String(ringCount);spacing.value=String(interval);summary.textContent=`${ringCount} × ${interval.toLocaleString()} m · outer ring ${(ringCount*interval).toLocaleString()} m`; }sync();const buttons=el('div',undefined,mount);Object.assign(buttons.style,{display:'flex',gap:'6px',flexWrap:'wrap'});const applyButton=el('button','Apply',buttons),stopButton=el('button','Stop following',buttons);for(const b of [applyButton,stopButton]){b.type='button';Object.assign(b.style,{border:'1px solid #C27A24',borderRadius:'999px',padding:'7px 12px',background:b===applyButton?'#C27A24':'#F8F2E7',color:b===applyButton?'#F8F2E7':'#3A3128',cursor:'pointer',font:'inherit'});}stopButton.disabled=true;
const rings=new GraphicsLayer({id:'live-follow-distance-rings',title:'Selected vehicle distance rings',listMode:'hide'});const source=()=>app.map.allLayers.find(l=>l.id===app.config.layerId);app.map.add(rings,Math.max(0,app.map.layers.indexOf(source())));const listeners=[];const on=(n,e,f)=>{n.addEventListener(e,f);listeners.push(()=>n.removeEventListener(e,f));};app.onCleanup(()=>{disposed=true;revision++;clearInterval(timer);abort.abort();listeners.forEach(f=>f());app.map.remove(rings);rings.destroy();mount.replaceChildren();});
function draw(p){const ds=distances();const graphics=ds.map((d,i)=>{const geometry=buffer.execute(p,d,{unit:'meters',maxDeviation:Math.max(0.2,d/200),curveType:'geodesic'});app.assert(geometry,'Could not generate a distance ring.');return new Graphic({geometry,symbol:{type:'simple-fill',style:'none',outline:{color:i===ds.length-1?'#E2A040':'#F1E7D6',width:i===ds.length-1?1.7:1.1}},attributes:{vehicle:name,radius_m:d},popupTemplate:{title:'{vehicle} · {radius_m} m',content:'Geodesic radius from the latest vehicle position.'}});});rings.removeAll();rings.addMany(graphics);}
let activeRequest=0;async function update(force=false,frame=false){if(disposed||!name)return {following:false};if(activeRequest&&!force)return lastResult;const request=++revision;activeRequest=request;const target=name;try{const l=source();app.assert(l,'Vehicle stream is unavailable.');const lv=await app.view.whenLayerView(l);const q=lv.createQuery();q.where='1=1';q.outFields=['vehiclename','time'];q.returnGeometry=true;const fs=await lv.queryLatestObservations(q,{signal:abort.signal});if(disposed||request!==revision||target!==name)return {superseded:true};const f=fs.features.find(f=>f.attributes.vehiclename===target);if(!f?.geometry||f.geometry.type!=='point'){status.textContent=`Waiting for ${target}…`;return {following:true,vehicle:target,waiting:true};}const p=f.geometry,moved=!lastPoint||p.x!==lastPoint.x||p.y!==lastPoint.y;if(force||moved){draw(p);lastPoint=p.clone();if(frame)await app.view.goTo(rings.graphics.getItemAt(rings.graphics.length-1).geometry.extent.clone().expand(1.4),{animate:false});else await app.view.goTo({center:p},{animate:false});}if(disposed||request!==revision)return {superseded:true};lastTime=f.attributes.time;const age=Math.max(0,Math.floor((Date.now()-Number(lastTime))/1000));status.textContent=`Following ${target} · ${age}s ago${age>30?' · stale':''}`;lastResult={following:true,vehicle:target,ringCount:rings.graphics.length,intervalMeters:interval,distances:distances(),unit:'meters',observationTime:lastTime,position:{x:p.x,y:p.y},connection:lv.connectionStatus};return lastResult;}catch(e){if(disposed)return;status.textContent=e.message;app.reportError(e);return {error:e.message};}finally{if(activeRequest===request)activeRequest=0;}}
app.actions.register('follow-vehicle',async input=>{const selected=input?.graphic?.attributes?.vehiclename??input?.name;app.assert(typeof selected==='string'&&selected.length,'Select a vehicle.');name=selected;revision++;lastPoint=null;stopButton.disabled=false;if(app.actions.has('inspect-live-vehicle'))await app.actions.invoke('inspect-live-vehicle',{name});return update(true,input?.frame!==false);});app.actions.register('configure-follow-rings',async input=>{const n=Number(input.ringCount),d=Number(input.intervalMeters);app.assert(Number.isInteger(n)&&n>=1&&n<=6,'Choose 1–6 rings.');app.assert(Number.isFinite(d)&&d>=1&&n*d<=100000,'Use a positive interval with an outer radius no greater than 100,000 m.');ringCount=n;interval=d;revision++;sync();if(name)return update(true,input?.frame!==false);return {following:false,ringCount,intervalMeters:interval,distances:distances()};});app.actions.register('stop-following-vehicle',()=>{revision++;name=null;lastPoint=null;lastTime=null;rings.removeAll();stopButton.disabled=true;status.textContent='Click a vehicle to follow.';return {following:false,ringCount:0};});app.actions.register('inspect-follow-rings',()=>({following:!!name,vehicle:name,ringCount:rings.graphics.length,configuredRingCount:ringCount,intervalMeters:interval,distances:distances(),numericInputCount:2,observationTime:lastTime,position:lastPoint?{x:lastPoint.x,y:lastPoint.y}:null}));app.actions.register('refresh-follow-rings',()=>update(true,false));on(applyButton,'click',()=>app.actions.invoke('configure-follow-rings',{ringCount:Number(count.value),intervalMeters:Number(spacing.value)}).catch(e=>{status.textContent=e.message;}));on(stopButton,'click',()=>app.actions.invoke('stop-following-vehicle'));timer=setInterval(()=>update(),app.config.refreshMs);
}